P=Path('docs/imports/new-gpt-20261031-b'); URL='https://chatgpt.com/share/6ae5b33f-e5a0-83ec-8e02-1b414683bea3'
rows=[]
def add(n,no,title,stem,opts,answer,student,explain,analyses,passage='',tables=None,refs=None):
 qid=f'q-{875+2*(n-1)}'; q={'id':qid,'sourceId':'src-more-052','subject':'Civics','title':f'公民第{no}題｜{title}','chapter':'綜合','volume':'綜合','date':'2026-10-30','dateLabel':'首次出題日期','addedAt':'2026-10-31','question':stem+'\n'+'\n'.join(f'({c}) {o}' for c,o in zip('ABCD',opts)),'answer':f'({answer}) {opts["ABCD".index(answer)]}','explanation':explain,'trap':'先區分程序中的身分、行為與責任，不把告訴、公訴、自訴或和解混用。','tags':[title,'法律訴訟'],'verification':'原卷逐題核對','verificationNote':'已實看本題原卷、完整四選項與必要材料；首次日期採原始使用者出題訊息的台灣日期，非考試日。','images':[f'assets/originals/src-more-052-original-{n:02}.webp'],'questionFigures':[],'explanationFigures':[],'tables':tables or [],'passage':passage,'sourceLabel':f'分享原卷｜第{no}題','studentAnswer':student,'correctOption':answer,'optionAnalysis':[{'label':c,'text':o,'wordClass':'應選' if c==answer else '不選','meaning':'','explanation':a} for c,o,a in zip('ABCD',opts,analyses)],'contentStatus':'完整原題','status':'todo','starred':False,'notes':''}
 if refs:q['explanation']+='\n\n法規核對：'+'；'.join(f'[{t}]({u})' for t,u in refs)+'。'
 (P/'questions'/f'{qid}.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n');rows.append({'id':qid,'originalNumber':str(no),'imageIndex':n,'questionPath':str(P/'questions'/f'{qid}.json'),'status':'curated_draft_pending_new_comic'})
def law(n,p='C0010001'):return f'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode={p}&flno={n}'
add(1,1,'兩種提告途徑', '右列是一則選舉衍生事件的新聞報導。文中的甲、乙兩部分，分別與何種刑事訴訟程序有關？',['甲＝自首；乙＝公訴','甲＝自訴；乙＝告訴','甲＝公訴；乙＝告發','甲＝告訴；乙＝公訴'],'B','A','甲是被害人委任律師，直接向法院提起自訴；乙是向檢察官申告犯罪的告訴。告訴是被害人的申告，公訴則是檢察官偵查後認為有起訴理由，向法院提起的訴訟，兩者不能互換。自首是犯罪者主動申告自己尚未被發覺的犯罪，與本題被害人提告不同。新聞提到偵查不公開，是當事人選擇途徑的說明，不代表所有偵查資料都永遠不能依法取得。',['甲的行為人是被害人，不是申告自己犯罪的自首者。','甲委任律師向法院自訴；乙向檢察官提出告訴，兩者均符合文意。','公訴由檢察官提起；乙是被害人申告，不是本題所考的一般第三人告發。','甲應為自訴；乙只是告訴，尚不能直接稱為公訴。'],passage='針對某政治人物的論文涉嫌抄襲，受害人選擇（甲）自行聘請律師提告。因為（乙）向檢察官提告的話，法律有偵查不公開的規定，證據掌握在檢方手中，無法查知對方如何答辯。',refs=[('刑事訴訟法第232條',law(232)),('刑事訴訟法第319、320條',law(319))])
add(2,3,'案件性質與撤回告訴','前中國小姐被名嘴爆料涉入緋聞案，當事人因此對該名嘴提告妨害名譽罪，並在接受媒體採訪時態度堅定表示絕對不會和解、撤告。根據內容判斷，文中提告的案件，性質與下列何者最為相似？',['積欠房租未繳','竊盜商店財物','不慎撞傷路人','超速遭到舉發'],'C','A','題幹的「不和解、撤告」引導辨認告訴乃論的刑事案件。妨害名譽罪原則上須告訴乃論；不慎撞傷路人涉及過失傷害，也屬告訴乃論，故C最相似。房租積欠主要是民事債務；一般竊盜商店財物是非告訴乃論刑事犯罪；單純超速舉發屬行政處罰。能和解不表示任何犯罪都會隨和解自動消失；告訴乃論案件仍須依法撤回告訴，才發生相應程序效果。',['主要是租約債務的民事爭議，與題幹刑事告訴乃論不同。','一般商店竊盜屬非告訴乃論，不因被害人撤告就當然終止追訴。','不慎撞傷涉及過失傷害，與本題妨害名譽同為告訴乃論類型。','單純超速舉發通常屬行政違規，與刑事訴訟不同。'],refs=[('刑法第314條',law(314,'C0000001')),('刑法第287條',law(287,'C0000001'))])
add(3,7,'公投票規定與責任','右列是《公民投票法》的其中一項規定，依據內容判斷，對於違反該規定的民眾，最可能面臨何種情況？',['因為不服該處罰而提起訴願','偵訊之後被檢察官提起公訴','在審理過程中度過18歲生日','同時被法官判處主刑與從刑'],'B','A','規定列出有期徒刑、拘役、罰金，這些是刑罰，表示行為人涉及刑事責任。檢察官偵查後認為證據足以起訴，可以向法院提起公訴，故四項以B最合理；不是說每案必然起訴。刑事判決的救濟不走行政訴願。題目未給行為人的年齡，不能推定審理時滿18歲；也不能由這條規定推出一定同時宣告從刑。',['訴願是針對行政處分的救濟；本規定列的是刑罰。','涉及刑事犯罪，有可能經偵查後由檢察官提起公訴。','未給年齡，不能推定生日或審理期間。','刑罰種類不代表每案必須同時宣告主刑和從刑。'],passage='將領得之公投票攜出場外者，處一年以下有期徒刑、拘役或科新臺幣一萬五千元以下罰金。',refs=[('公民投票法第41條','https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=D0020050&flno=41'),('刑事訴訟法第251條',law(251))])
add(4,17,'和解後的刑事責任','右列是一則社會新聞，根據報導內容及我國法律規範判斷，下列各項解讀何者正確？',['侵占屬於非告訴乃論的犯罪類型','被害人提告侵占就是要提起公訴','雙方可聲請調解，結束所有糾紛','警察受理提告，偵查後起訴嫌犯'],'A','B','男子侵占他人遺留的鈔票，題幹又明示歸還、和解後仍有刑事責任，對應本案非告訴乃論的性質，選A。被害人提出的是告訴，公訴由檢察官提起；警察受理、調查後呈送檢察官，並不負責起訴。和解可以處理返還或賠償，也可能影響量刑，但不當然消滅非告訴乃論案件的刑事追訴。此處依題目陌生人間的情境判斷，不把親屬間侵占的特別規定混進來。',['本案和解後仍須承擔刑責，符合非告訴乃論的性質。','告訴是被害人的申告；公訴的提起者是檢察官。','民事賠償可協商，但不能保證一併終結本案刑事責任。','警察調查犯罪；是否起訴由檢察官決定。'],passage='一名男子在提款時，發現前一位使用者忘記拿走的鈔票，就收為己用。事後被提告侵占，才趕緊歸還並與被害人達成賠償和解，但仍須背負刑事責任。',refs=[('刑法第337、338條',law(337,'C0000001')),('刑事訴訟法第251條',law(251))])
add(5,18,'事故調查與刑事角色','某位被停職中的員警開車擦撞機車卻逕行離去，受傷的機車車主隨即報案，該涉案員警被移送法辦。偵訊時他坦承當時想睡覺精神恍惚，以為只是小擦撞，並不構成事故，所以才未下車察看。對上述涉案員警的敘述，何者正確？',['擦撞到機車屬於故意行為','偵訊後案件移送給書記官','涉案員警須負擔刑事責任','對該涉案員警可直接審判'],'C','B','題目有擦撞致人受傷及移送法辦的線索，涉及過失傷害等刑事責任，四項以C最合題意。想睡覺、精神恍惚不等於法律上的當然免責，也不能反推擦撞是故意。書記官處理筆錄、文書等事務，並非負責偵查、起訴的檢察官；受理報案也不等於可以跳過法定程序直接審判。具體罪名與成立要件仍須法院依證據認定，本題不僅憑離開現場就斷言特定肇逃罪一定成立。',['題幹不能證明他有意撞人，可能是過失。','偵查、起訴由檢察官負責，書記官並非案件起訴者。','擦撞致人受傷涉及刑事責任，精神恍惚不能當作自動免責。','仍須經法定偵查、起訴及法院審理，不能直接跳過程序。'],refs=[('刑法第284條',law(284,'C0000001')),('刑事訴訟法第251條',law(251))])
add(6,21,'話劇中的訴訟角色','八年一班要表演我國法律訴訟的話劇，依據以下三位同學臺詞內容判斷，對於此話劇的各項建議與解讀，下列何者正確？',['劇中小智最後的判決結果，會出現罰鍰與褫奪公權','小榮的同事可以指揮小惠，調查犯罪嫌疑人的背景','為了詳述角色，可以加入小智主動調查證據的劇情','話劇中的案件，當事人都不能經由調解來結束糾紛'],'B','D','原卷預期B：小惠接受指揮、在第一線偵查呈報，是警察；小智依證據獨立審判，是法官；小榮指揮刑罰執行，是檢察官。因此同為檢察官的同事可以依法指揮司法警察調查犯罪。\n\n但C不能用「法官絕不主動調查證據」排除：《刑事訴訟法》第163條明定法院為發見真實得依職權調查證據，部分重大事項還應依職權調查。因此原卷的單選措辭有歧義；保留預期B，並將C的法律範圍列為待確認，不教成法官一概不能主動調查。A混用行政罰鍰與刑罰；D也不能由臺詞斷言所有案件都不可調解。',['此處呈現刑事訴訟，刑事金錢刑用罰金，不能把罰鍰當成刑罰。','檢察官依法指揮司法警察偵查，小榮與其同事的職務支持此項。','原卷預期不選，但法官依法得依職權調查證據；其籠統文字另有正確解讀，已列單選疑義。','臺詞不足以確定案件類型；部分民事或告訴乃論刑事糾紛可以依法調解。'],passage='小惠：「我接受指揮，在第一線偵查犯罪並呈報。」\n小智：「為了伸張正義，我必須基於證據獨立審判。」\n小榮：「我指揮執行判決的結果，讓被告接受刑罰。」',refs=[('刑事訴訟法第163條',law(163)),('刑事訴訟法第229、230條',law(229)),('刑事訴訟法第457條',law(457))])
add(7,24,'自訴的提出與舉證','我國曾經發生立法委員提出自訴，指控前總統涉嫌教唆洩密的案件。經過纏訟多年，最後法院宣判前總統無罪。對上述案件的解讀，下列何者最合理？',['該立法委員須委任律師才可以提起此類訴訟','檢察官必須向法官舉證被告的犯罪相關證據','審理這項案件的法官也可以審理總統彈劾案','該立法委員可以請求警察協助收集犯罪證據'],'A','D','題幹明示「自訴」，依《刑事訴訟法》第319條，提起自訴應委任律師，A有明確依據。自訴的舉證主要由自訴人及其代理律師負擔，不能套成公訴案件由檢察官舉證。普通刑事案件與總統彈劾案的審理制度不同。自訴人需要調查證據時，可依法向法院聲請；不能把自己當成檢察官，直接指揮警察蒐證。D依本題比較程序的意思不選，不解成當事人連提供線索或依法向法院聲請都不行。',['自訴須委任律師，是法律明確規定。','自訴不是由檢察官提起公訴並負通常公訴舉證責任的案件。','總統彈劾案屬憲法法庭審理，不是普通刑事法院的同一職權。','自訴人不得自行指揮司法警察；需調查證據時依法向法院聲請。'],refs=[('刑事訴訟法第319條',law(319)),('刑事訴訟法第161、343條',law(343)),('刑事訴訟法第163條',law(163))])
add(8,1,'按鈴申告與告訴資格','新聞媒體經常可以見到類似右列的報導，依據我國法律，下列對於圖中事件的敘述，何者正確？',['此為該候選人能提出訴訟的唯一途徑','候選人按鈴申告的地點應為當地法院','由文中敘述可知候選人並不是提出民事訴訟','對名嘴不滿的觀眾可使用相同程序提出告訴'],'C','D','按鈴申告在此指向檢察機關申告妨害名譽等犯罪，是刑事程序，所以C正確。被害人也可能依法委任律師自訴，或另行主張民事損害賠償，不是唯一途徑。按鈴申告通常到地方檢察署，而非把法院與檢察署混為一處。告訴須有法定告訴權；一般觀眾只因不滿名嘴，並不因此成為這次名譽受侵害案件的被害人。第三人的告發和有告訴權者的告訴也要區分。',['刑事告訴、自訴與民事求償須依各自條件辦理，並非只有按鈴申告。','此處指向地方檢察署申告犯罪，不是到普通法院按鈴。','文中為犯罪申告，屬刑事程序；不等於已提出民事訴訟。','單純不滿不會產生此案告訴權；告發也不等於被害人提出告訴。'],passage='立法委員候選人不滿被某位名嘴在政論節目中指控貪汙，今日前往按鈴申告，表示將以司法程序證明自身清白。',refs=[('刑事訴訟法第232、240條',law(232)),('刑事訴訟法第242條',law(242))])
add(9,1,'調解與判決件數','右圖為我國某縣的地方法院在一年內的刑事案件判決總數，以及其中屬於告訴乃論刑事案件判決的件數。若上述案件其中的一部分當初在調解委員會調解成功，則關於圖中甲、乙線段的位置，下列何種變化最可能發生？',['甲線段上移，乙線段上移','甲線段上移，乙線段不變','甲線段下移，乙線段下移','甲線段下移，乙線段不變'],'C','D','甲是全部刑事案件判決數，乙是其中告訴乃論案件的判決數，乙包含在甲內。依本題「當初先調解成功」而少了部分進入判決的告訴乃論案件的比較情境，乙減少，甲總數也跟著減少，故兩線都下移，選C。法律上並非只要和解就必然少一件判決；調解成立、依法撤回告訴或自訴及其時點等仍須符合要件。這裡比較的是題設的件數變化，不是預測每個現實月份一定同幅下降。',['先行調解使部分案件不進入判決，不能推成兩項都增加。','甲也包括乙；乙受影響而減少，不能推成總數增加。','乙是甲的子集合，少了乙中的部分判決，兩者件數都減少。','錯在乙不變：先受影響的是可調解的告訴乃論案件判決數。'],refs=[('鄉鎮市調解條例第1、28、30條','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=I0020003')])
add(10,4,'案件分類與件數','右表是老師在課堂上以我國某地訴訟案件的種類及數目作為舉例，根據圖表內容判斷，下列推論何者正確？',['由檢察官提起公訴的最多18件','可以聲請調解的最多67件','可以私下和解結束糾紛共有85件','可以由原告提起自訴的共有35件'],'B','A','本題按鄉鎮市調解委員會的法定調解範圍，民事事件及告訴乃論刑事事件可聲請調解，因此甲32＋乙35＝67件，B正確。告訴乃論案件在有合法告訴的前提下，也可能由檢察官提起公訴，不能把公訴限為丙18件。非告訴乃論案件即使就民事賠償和解，也不當然終止刑事追訴。自訴也不是乙35件的同義詞；依法符合條件的非告訴乃論案件也可能自訴。這個67件是依原表四類事件及本題調解範圍計算，不是把所有刑事附帶民事求償另算一輪。',['乙告訴乃論案件也可能經合法告訴後由檢察官公訴，不能只算丙。','依本題鄉鎮市調解範圍，甲32＋乙35＝67件。','甲乙丙雖合85件，但丙的刑事責任不能因私下和解就一概消滅。','告訴乃論與自訴是不同分類，不能把自訴案件數直接等同乙35件。'],tables=[{'caption':'我國某地訴訟案件的種類及數目','headers':['代號','案件種類','數目'],'rows':[['甲','民事案件','32件'],['乙','告訴乃論刑事案件','35件'],['丙','非告訴乃論刑事案件','18件'],['丁','行政訴訟案件','10件']]}],refs=[('鄉鎮市調解條例第1條','https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=I0020003&flno=1'),('刑事訴訟法第319條',law(319))])
add(11,5,'免刑與不同法律責任','一對母子發生爭執，兒子拿起手機錄影時被母親拍落，使手機螢幕碎裂。兒子對此到警察局報案，提告毀損。法官審酌被告情況與案情後，依法做出「免刑」判決，免去被告在此訴訟案件中的責任。針對以上案件內容的解讀，下列何者最為適當？',['法官判決免刑使被告不用承擔損害賠償責任','即使判決免刑被告仍須承擔契約不履行責任','此案件的判決結果符合罪刑法定原則的意涵','此案件在審理的過程中不會有檢察官的介入'],'C','A','「依法」免刑也屬依法律作成刑事裁判，並不是法官任意取消刑罰，故C符合罪刑法定原則。免刑處理的是刑事處罰，不等於免去手機毀損造成的民事賠償；民事責任仍依其要件判斷。本案並未給母子間有契約約定，不能硬套契約不履行。兒子到警察局報案、提告的途徑可能經檢察官偵查、起訴，不能說審理過程一定沒有檢察官；且告訴乃論不等於沒有公訴。免刑也不同於無罪，不將兩者混用。',['刑事免刑不會當然消滅民事損害賠償責任。','題目沒有契約義務的依據，毀損通常討論侵權行為賠償。','依法定規範作成免刑判決，仍符合罪刑法定要求。','從警局受理至公訴程序可有檢察官參與，不能一概排除。'],refs=[('刑法第1條',law(1,'C0000001')),('民法第184條',law(184,'B0000001')),('刑法第357條',law(357,'C0000001'))])
